-- Synthetic opencode v2 store for the summary matrix; the sandbox builds opencode.db from this.
-- Times are epoch ms on 2026-06-01..07 09:00Z; m-offsets are minutes after that.
CREATE TABLE session_v2(id TEXT PRIMARY KEY, project_id TEXT NOT NULL, parent_id TEXT, directory TEXT NOT NULL, title TEXT, model TEXT, agent TEXT, time_created INTEGER NOT NULL, time_updated INTEGER NOT NULL);
CREATE TABLE session_message(id TEXT PRIMARY KEY, session_id TEXT NOT NULL, type TEXT NOT NULL, seq INTEGER NOT NULL, time_created INTEGER NOT NULL, time_updated INTEGER NOT NULL, data TEXT NOT NULL, UNIQUE(session_id, seq));

-- oc1: finished

-- oc2: finished, then compacted (opencode writes the summary as an assistant message)

